[
  {
    "id": "social-workers-low-automation",
    "source": "If you’re in a career that involves a good deal of social perceptiveness, such as a healthcare social worker or a speech language pathologist (both at < 1% likelihood of automation), there's little need to worry about automation.",
    "claim": "Healthcare social workers have an automation probability of 0.0035 and speech-language pathologists 0.0064, both below 0.01.",
    "tables": {
      "jobs": "data/all_jobs_updated_to_BLO.csv"
    },
    "code": "jobs.loc[jobs.Occupation.isin(['Healthcare Social Workers','Speech-Language Pathologists']), ['Occupation','Probability']]"
  },
  {
    "id": "medical-assistants-601000",
    "source": "Most of us fall somewhere in between those two extremes, and may be happy enough knowing that robots won’t be stealing our jobs quite yet (here’s looking at you, 601,000 medical assistants).",
    "claim": "Medical assistants number 601,240 in the employment counts.",
    "tables": {
      "jobs": "data/all_jobs_updated_to_BLO.csv"
    },
    "code": "jobs.assign(emp=pd.to_numeric(jobs['number'].astype(str).str.replace(',',''), errors='coerce')).loc[lambda d: d.Occupation=='Medical Assistants', ['Occupation','emp']]"
  },
  {
    "id": "top-automatable-jobs-50-million",
    "source": "if only the top 15% of the most vulnerable occupations disappear, over 50 million people risk being out of work",
    "claim": "Occupations with an automation likelihood of at least 85% employ 51,960,340 people.",
    "tables": {
      "jobs": "data/all_jobs_updated_to_BLO.csv"
    },
    "code": "jobs.assign(emp=pd.to_numeric(jobs['number'].astype(str).str.replace(',',''), errors='coerce')).query('Probability >= 0.85').emp.sum()"
  },
  {
    "id": "truck-drivers-79-percent",
    "source": "truck drivers — who have a 79% chance of becoming automated",
    "claim": "Heavy and tractor-trailer truck drivers have an automation probability of 0.79.",
    "tables": {
      "jobs": "data/all_jobs_updated_to_BLO.csv"
    },
    "code": "jobs.loc[jobs.Occupation=='Heavy and Tractor-Trailer Truck Drivers', ['Occupation','Probability']]"
  },
  {
    "id": "truckers-one-percent-workforce",
    "source": "Truckers make up over 1% of the U.S. working population",
    "claim": "Heavy and tractor-trailer truck drivers account for 1.3956% of total employment across the occupations in the data, more than 1%.",
    "tables": {
      "jobs": "data/all_jobs_updated_to_BLO.csv"
    },
    "code": "jobs.assign(emp=pd.to_numeric(jobs['number'].astype(str).str.replace(',',''), errors='coerce')).pipe(lambda d: d.loc[d.Occupation=='Heavy and Tractor-Trailer Truck Drivers','emp'].sum()/d.emp.sum()*100)"
  },
  {
    "id": "nearly-every-county-job-loss",
    "source": "Were jobs with a high risk of automation to vanish, a staggering number of people in nearly every county in America would be out of a job.",
    "claim": "In 3,139 of the 3,143 county rows (99.87%), at least 10% of jobs are in occupations with an 85% or higher automation likelihood.",
    "tables": {
      "counties": "data/final_puma2county_minified_v2.csv"
    },
    "code": "counties.puma_jobslostat85.ge(0.10).agg(['sum','count','mean'])"
  }
]

[
  {
    "source": "truck drivers — who have a 79% chance of becoming automated — to be the most popular job in over 20 states",
    "why": "The data files contain no state-by-state occupation counts. The 20-state ranking comes from the external NPR map linked in the story, not from these tables."
  },
  {
    "source": "Even in the northeast, where states can be expected to be somewhat less affected, many counties would lose nearly 30% of jobs.",
    "why": "The county file does not reproduce this. Its northeastern counties (CT, ME, MA, NH, NJ, NY, PA, RI, VT) have a mean job-loss share of about 39% and a minimum of 28.1%; only 2 of 217 counties are at or below 30%, so 'many counties ... nearly 30%' is not supported by the data."
  },
  {
    "source": "In 90% of states, jobs that are highly susceptible to automation are filled by white Americans.",
    "why": "Neither provided file has race or ethnicity counts. The story's state-level white/non-white aggregation uses IPUMS Census microdata that is not included in data/."
  },
  {
    "source": "VOTERS WHO WILL: Lean conservative / Lean progressive — Maine 95% 5%, West Virginia 94% 6%, New Hampshire 93% 7%, ...",
    "why": "The state-by-state white and non-white shares of workers in highly automatable jobs are not in either file; the county file contains only total county job-loss shares."
  },
  {
    "source": "In these states, people at risk of losing their jobs due to automation tend to be white — this tips the scales in every single swing state in favor of the Republican party.",
    "why": "Requires state-level race breakdowns of at-risk workers and a swing-state classification, neither of which is present in the data."
  },
  {
    "source": "When trade adversely affected employment prospects in white areas, voters reacted by veering to the right, electing conservative Republicans.",
    "why": "This is a finding of the cited Autor, Dorn, Hanson, and Majlesi paper on Chinese trade exposure, not a computation from the Frey-Osborne/BLS employment files."
  },
  {
    "source": "Conversely, in predominantly non-white districts, voters were much more likely to elect progressive Democrats.",
    "why": "Same external paper; the provided files contain no electoral or race data."
  },
  {
    "source": "The political shift from the center to the extremes was clear.",
    "why": "This is the external trade paper's conclusion; no electoral data is provided in data/."
  }
]

