cd /home/user/RL_Study/report-gepa/runs/originals/jobs && ls -la facts.json skipped.json && python3 - <<'EOF'
import json
for fn in ['facts.json','skipped.json']:
    d=json.load(open(fn))
    print(fn, len(d), 'entries')
    if fn=='facts.json':
        for f in d: print(' -', f['id'])
    else:
        for s in d: print(' -', s['source'][:90].replace('\n',' '))
EOF

cd /home/user/RL_Study/report-gepa/runs/originals/jobs && python3 - <<'EOF'
import json, pandas as pd, numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    env={'pd':pd,'np':np}
    for k,p in f['tables'].items(): env[k]=pd.read_csv(p)
    print('='*60); print(f['id']); print('CLAIM:',f['claim']); print(eval(f['code'],env))
EOF
